// Clean Rows
// 1. COLUMNS = the exact column names in your n8n Data Table (only these are sent).
// 2. ALIASES = other headings the SharePoint tracker might use for the same column.
// 3. TYPES   = 'string' (default), 'number', 'numberText' (plain number stored as text, e.g. 1157.44)
//             or 'date' – match your Data Table column types
//             (the Column list in the Data Table node shows each type, e.g. "Invoice (number)").
//             'date' also turns Excel serial dates (e.g. 46118) into 2026-04-06.
// 4. KEY     = the column that identifies a row (matches existing rows so they are not duplicated).
const COLUMNS = ['Invoice', 'Value', 'Customer', 'Company_Code', 'Project_Manager', 'Name_the_PortalEmail_ID',
  'Received_Date', 'Allocated_Date', 'Invoice_Date'];
const ALIASES = {
  Invoice: ['invoice', 'invoice no', 'invoice number', 'invoice #', 'inv no'],
  Value: ['value', 'amount', 'invoice value'],
  Customer: ['customer', 'customer name', 'client'],
  Company_Code: ['company code', 'coco', 'co code', 'company_code'],
  Project_Manager: ['project manager', 'pm', 'manager'],
  Name_the_PortalEmail_ID: ['name the portal email id', 'portal email id', 'portal email', 'portal', 'email id',
    'submission portal'],
  Received_Date: ['received date', 'date received', 'received'],
  Allocated_Date: ['allocated date', 'date allocated', 'allocated'],
  Invoice_Date: ['invoice date', 'inv date'],
};
const TYPES = { Invoice: 'number', Value: 'numberText', Received_Date: 'date', Allocated_Date: 'date', Invoice_Date: 'date' };
const KEY = 'Invoice';
const UPPER = ['Customer', 'Company_Code']; // made upper case so spelling variants group together
// The tracker sometimes holds the sales org instead of the company code. Left = sales org, right = real company code.
const COMPANY_CODE_FIX = { G36C: 'G367', GS5C: 'G367' };

const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const lookup = new Map();
for (const col of COLUMNS) {
  lookup.set(norm(col), col);
  for (const a of ALIASES[col] || []) lookup.set(norm(a), col);
}
// Excel serial day numbers (e.g. 46118 = 2026-04-06); the time of day is ignored
const fromSerial = (n) => (n >= 20000 && n <= 80000
  ? new Date(Date.UTC(1899, 11, 30) + Math.floor(n) * 86400000).toISOString().slice(0, 10) : null);
const pad = (n) => String(n).padStart(2, '0');
const convert = (col, v) => {
  if (v === '' || v == null) return null;
  if (TYPES[col] === 'number' || TYPES[col] === 'numberText') {
    if (typeof v === 'number') return Number.isFinite(v) ? (TYPES[col] === 'number' ? v : String(v)) : null;
    let t = String(v).trim().replace(/[\s,$€£]/g, '');
    const negative = /^\(.*\)$/.test(t) || t.startsWith('-'); // (1157.44) and -1157.44 are negative amounts
    t = t.replace(/^\((.*)\)$/, '$1').replace(/^-/, '');
    if (TYPES[col] === 'number') t = t.replace(/\.0+$/, '');
    // whole value must be a plain number: "7001 / 7002" or "INV-12" are not guessed
    if (!(TYPES[col] === 'number' ? /^\d+$/ : /^\d*\.?\d+$/).test(t)) return null;
    const n = Number(t) * (negative ? -1 : 1);
    return TYPES[col] === 'number' ? n : String(n);
  }
  if (TYPES[col] === 'date') {
    if (typeof v === 'number') return fromSerial(v);
    const t = String(v).trim();
    if (/^\d{5}(\.\d+)?$/.test(t)) return fromSerial(Number(t));
    const iso = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;
    const d = new Date(t); // e.g. 4/6/2026 (US order) or "Apr 6, 2026"
    return isNaN(d) ? null : `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  }
  const text = String(v).replace(/\s+/g, ' ').trim();
  const out = UPPER.includes(col) ? text.toUpperCase() : text;
  return col === 'Company_Code' && COMPANY_CODE_FIX[out] ? COMPANY_CODE_FIX[out] : out;
};

// Stop early on the wrong file / wrong tab instead of saving nothing
const input = $input.all().filter((i) => Object.keys(i.json || {}).length);
if (!input.length) throw new Error('The uploaded sheet is empty. Check the file and the Sheet Name option on "Read Tracker Sheet". Nothing was changed.');
// Excel leaves empty cells out of a row, so collect the headings from every row
const headings = [...new Set(input.flatMap((i) => Object.keys(i.json)))];
if (!headings.some((h) => lookup.get(norm(h)) === KEY)) {
  throw new Error(`No "${KEY}" column found. Headings in the sheet: ${headings.join(', ')}. ` +
    'Check the file, the Sheet Name option on "Read Tracker Sheet", or add the heading to ALIASES. Nothing was changed.');
}

const rows = new Map();
for (const { json: raw } of input) {
  const row = {};
  for (const [header, value] of Object.entries(raw)) {
    const col = lookup.get(norm(header));
    if (col && row[col] == null) row[col] = convert(col, value);
  }
  if (row[KEY] == null || row[KEY] === '') continue; // blank / totals rows
  for (const col of COLUMNS) if (!(col in row)) row[col] = null;
  rows.set(String(row[KEY]), row); // a repeated key keeps the last row
}
return [...rows.values()].map((json) => ({ json }));

// Add Lookups — fill SAP customer code, profit centre and product line from the ZSD log and the Tableau extract.
// Matching is on invoice number only. Nothing is guessed: no match = the value stays empty.
// Values found on an earlier upload are kept, so an invoice that is no longer in a later Tableau extract keeps its codes.
const TABLEAU_COMPANY_CODES = ['3060', '3485', '3487', 'G367']; // other company codes in the Tableau extract are ignored
// Clearwater (G367): product line PQP when Tableau does not give one
const CLEARWATER = { companyCode: 'G367', Product_Line: 'PQP' };
const SOURCES = [ // the read steps, in order of preference for the SAP customer code
  { step: 'Read ZSD Log', label: 'ZSD' },
  { step: 'Read ZSD 2025 Sheet', label: 'ZSD' },
  { step: 'Read Tableau Extract', label: 'Tableau' },
];

const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
// cleaned value for matching: "0007001212645", " 7,001,212,645 ", "'7001212645" and 7001212645.0 all become 7001212645
const key = (v) => {
  let t = String(v ?? '').trim().replace(/^'/, '').replace(/\.0+$/, '');
  if (/^[\d\s,]+$/.test(t)) t = t.replace(/[\s,]/g, '').replace(/^0+(?=\d)/, '');
  return t;
};
const tidy = (v) => String(v ?? '').replace(/\s+/g, ' ').trim().toUpperCase(); // profit centre as text, e.g. GPJ908
const rows = $('Clean Rows').all().map((i) => ({ ...i.json, Sales_Org: null, SAP_Customer_Code: null, Profit_Center: null, Product_Line: null }));
const wanted = new Set(rows.map((r) => key(r.Invoice)));

// rows from one read step (a missing file or sheet gives an error item, which is skipped)
const readRows = (step) => {
  try { return $(step).all().map((i) => i.json).filter((j) => j && !j.error && Object.keys(j).length > 1); }
  catch (e) { return []; }
};
// the column whose values match the most tracker invoice numbers is the invoice column
const invoiceColumn = (data) => {
  const hits = {};
  for (const r of data) for (const [h, v] of Object.entries(r)) if (wanted.has(key(v))) hits[h] = (hits[h] || 0) + 1;
  return Object.entries(hits).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0] ?? null;
};
// the column that passes `test` for the most rows
const columnBy = (data, test) => {
  const counts = {};
  for (const r of data) for (const [h, v] of Object.entries(r)) if (test(norm(h), v) && key(v)) counts[h] = (counts[h] || 0) + 1;
  return Object.entries(counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0] ?? null;
};
const isCustomerCode = (h, v) => /customer|sold to|payer/.test(h) && !/name|key|group|country|type/.test(h)
  && /^[A-Za-z]?\d{3,}$/.test(key(v)); // e.g. 89598 or 160026
const isProfitCentre = (h) => /profit/.test(h);
const isProductLine = (h) => /product/.test(h) && !/desc|name/.test(h); // e.g. PTI, AIS, PTR, GIS

const found = { customer: new Map(), profit: new Map(), product: new Map(), salesOrg: new Map() };
const SALES_ORGS = ['G36C', 'GS5C']; // sales orgs of G367 (same list as COMPANY_CODE_FIX in "Clean Rows")
const isSalesOrg = (h) => /sales org|sorg/.test(h);

// the tracker may hold the sales org in its company code column: keep it before it was changed to G367
{
  const raw = $('Read Tracker Sheet').all().map((i) => i.json);
  const heads = [...new Set(raw.flatMap((r) => Object.keys(r || {})))];
  const ccHead = heads.find((h) => ['company code', 'coco', 'co code', 'company_code'].includes(norm(h)));
  const invHead = heads.find((h) => ['invoice', 'invoice no', 'invoice number', 'invoice #', 'inv no'].includes(norm(h)));
  if (ccHead && invHead) {
    for (const r of raw) {
      const so = String(r[ccHead] ?? '').trim().toUpperCase();
      if (SALES_ORGS.includes(so)) found.salesOrg.set(key(r[invHead]), so);
    }
  }
}
const notes = [];
for (const { step, label } of SOURCES) {
  let data = readRows(step);
  if (label === 'Tableau') { // keep only the company codes we report on
    const ccCol = columnBy(data, (h) => h === 'company code');
    if (ccCol) data = data.filter((r) => TABLEAU_COMPANY_CODES.includes(tidy(r[ccCol])));
  }
  if (!data.length) continue;
  const inv = invoiceColumn(data);
  if (!inv) { notes.push(`${step}: no invoice numbers matched the tracker`); continue; }
  const cust = columnBy(data, isCustomerCode);
  const prof = label === 'Tableau' ? columnBy(data, isProfitCentre) : null;
  // a heading with "line" in it wins for product line ("Product Line" over "Product")
  const prod = label === 'Tableau' ? (columnBy(data, (h) => isProductLine(h) && /line/.test(h)) || columnBy(data, isProductLine)) : null;
  const sorg = label === 'ZSD' ? columnBy(data, (h, v) => isSalesOrg(h) && SALES_ORGS.includes(tidy(v))) : null;
  let matched = 0;
  for (const r of data) {
    const k = key(r[inv]);
    if (!wanted.has(k)) continue;
    matched++;
    if (cust && key(r[cust]) && !found.customer.has(k)) found.customer.set(k, key(r[cust]));
    if (prof && key(r[prof]) && !found.profit.has(k)) found.profit.set(k, tidy(r[prof]));
    if (prod && key(r[prod]) && !found.product.has(k)) found.product.set(k, tidy(r[prod]));
    if (sorg && SALES_ORGS.includes(tidy(r[sorg])) && !found.salesOrg.has(k)) found.salesOrg.set(k, tidy(r[sorg]));
  }
  notes.push(`${step}: ${matched} matching rows (invoice column "${inv}"` +
    (cust ? `, customer code "${cust}"` : ', no customer code column found') +
    (label === 'Tableau' ? `, profit centre ${prof ? `"${prof}"` : 'not found'}, product line ${prod ? `"${prod}"` : 'not found'})` : ')'));
}

// values saved on earlier uploads (read by "Check Table" before anything is changed)
const before = new Map();
for (const { json: t } of $('Check Table').all()) if (t && t.Invoice != null) before.set(key(t.Invoice), t);

for (const r of rows) {
  const k = key(r.Invoice);
  const old = before.get(k) || {};
  r.SAP_Customer_Code = found.customer.get(k) ?? old.SAP_Customer_Code ?? null;
  r.Profit_Center = found.profit.get(k) ?? old.Profit_Center ?? null;
  r.Product_Line = found.product.get(k) ?? old.Product_Line ?? null;
  if (String(r.Company_Code) === CLEARWATER.companyCode) {
    r.Product_Line = r.Product_Line ?? CLEARWATER.Product_Line;
    r.Sales_Org = found.salesOrg.get(k) ?? old.Sales_Org ?? null;
  }
}
// which columns were used is shown on the Done page; "_lookupNotes" is removed again before saving
if (rows.length) rows[0]._lookupNotes = notes.length ? notes.join(' · ') : 'no ZSD log or Tableau extract uploaded';
return rows.map((json) => ({ json }));

// Safety Check – runs BEFORE the table is emptied.
// If anything is wrong it stops here with a clear message, and the Data Table is left exactly as it was.
const rows = $('Add Lookups').all();
if (!rows.length) {
  throw new Error('No rows with an invoice number were found in the file. Nothing was changed.');
}
const columns = Object.keys(rows[0].json).filter((k) => !k.startsWith('_')); // the columns that will be saved
const sample = $('Check Table').first().json || {}; // an existing row of the Data Table (empty if the table is empty)
const tableColumns = Object.keys(sample);
if (tableColumns.length) {
  const missing = columns.filter((c) => !tableColumns.includes(c));
  if (missing.length) {
    throw new Error(`The Data Table has no column called: ${missing.join(', ')}. ` +
      'Check that "Check Table", "Clear Table" and "Save All Rows" all point to the right Data Table, ' +
      'or add the missing column(s) to the Data Table (type: string). Nothing was changed.');
  }
}
return [{ json: { rowsToSave: rows.length, tableHadRows: tableColumns.length > 0 } }];

// Rows to Save — after the table is cleared, pass all rows (with the looked-up codes) to the bulk save.
// Helper fields starting with "_" are not saved.
return $('Add Lookups').all().map((i) => ({
  json: Object.fromEntries(Object.entries(i.json).filter(([k]) => !k.startsWith('_'))),
}));

// Summarise Upload — counts and data quality checks for the confirmation page.
// Fixed rules only (no clock, no randomness): the same file always gives the same result.
const KEY = 'Invoice';
const KEY_ALIASES = ['invoice', 'invoice no', 'invoice number', 'invoice #', 'inv no']; // keep in step with Clean Rows
const EARLIEST_DATE = '2020-01-01';
const DATE_COLUMNS = ['Received_Date', 'Allocated_Date', 'Invoice_Date'];
const LIST_LIMIT = 10;
const FILE_NAME = $('Upload Tracker').first().binary?.Tracker_File?.fileName ?? 'tracker';

const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const keyNames = new Set([KEY, ...KEY_ALIASES].map(norm));
const num = (v) => {
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};

// Raw sheet: blank-key rows and repeated invoices
const raw = $('Read Tracker Sheet').all().map((i) => i.json);
const seen = new Map();
const unreadable = []; // invoice cells that are not a plain number (e.g. "7001 / 7002"): skipped, not guessed
let blank = 0;
for (const r of raw) {
  const h = Object.keys(r).find((k) => keyNames.has(norm(k)));
  const id = h == null ? '' : String(r[h] ?? '').trim();
  if (!/\d/.test(id)) { blank++; continue; } // empty, or a label such as "Total"
  if (!/^\d+(\.0+)?$/.test(id.replace(/[\s,]/g, ''))) { unreadable.push(id); continue; }
  seen.set(id, (seen.get(id) || 0) + 1);
}
const duplicates = [...seen].filter(([, n]) => n > 1).map(([id]) => id).sort();

// Cleaned rows: quality checks
const rows = $('Clean Rows').all().map((i) => i.json);
const checks = {
  'missing value': (r) => num(r.Value) === null,
  'zero or negative value': (r) => num(r.Value) !== null && num(r.Value) <= 0,
  'missing customer': (r) => !r.Customer,
  'missing company code': (r) => !r.Company_Code,
  'no readable date': (r) => DATE_COLUMNS.every((c) => !r[c]),
  [`date before ${EARLIEST_DATE}`]: (r) => DATE_COLUMNS.some((c) => r[c] && r[c] < EARLIEST_DATE),
  'allocated before received': (r) => r.Allocated_Date && r.Received_Date && r.Allocated_Date < r.Received_Date,
};
const issues = {};
for (const [label, test] of Object.entries(checks)) {
  const ids = rows.filter(test).map((r) => String(r[KEY]));
  if (ids.length) issues[label] = { count: ids.length, examples: ids.slice(0, LIST_LIMIT) };
}

const fmt = (n) => n.toLocaleString('en-US');
// how many rows were actually written (only present when the "Compare with Table" step is used)
const written = (() => {
  try { return $('Compare with Table').all().filter((i) => i.json.Invoice !== undefined && i.json.Invoice !== null && i.json.Invoice !== '').length; }
  catch (e) { return null; }
})();
const parts = written === null
  ? [`${fmt(rows.length)} invoices saved from ${fmt(raw.length)} rows`]
  : [`${fmt(rows.length)} invoices in the file (${fmt(raw.length)} rows) · ${fmt(written)} new or changed rows saved, the rest were already up to date`];
if (blank) parts.push(`${fmt(blank)} blank or total rows skipped`);
if (unreadable.length) {
  parts.push(`${fmt(unreadable.length)} rows skipped because the invoice number is not a plain number: ` +
    unreadable.slice(0, LIST_LIMIT).join(', ') + (unreadable.length > LIST_LIMIT ? ', …' : ''));
}
if (duplicates.length) {
  parts.push(`${fmt(duplicates.length)} invoices appear more than once (last row kept): ` +
    duplicates.slice(0, LIST_LIMIT).join(', ') + (duplicates.length > LIST_LIMIT ? ', …' : ''));
}
for (const [label, { count, examples }] of Object.entries(issues)) {
  parts.push(`${fmt(count)} with ${label} (e.g. ${examples.slice(0, 3).join(', ')})`);
}
// SAP customer code / profit centre coverage (only when the "Add Lookups" step is used)
try {
  const looked = $('Add Lookups').all().map((i) => i.json);
  const pcRows = looked;
  parts.push(`SAP customer code found for ${fmt(looked.filter((r) => r.SAP_Customer_Code).length)} of ${fmt(looked.length)} invoices` +
    ` · profit centre found for ${fmt(pcRows.filter((r) => r.Profit_Center).length)} of ${fmt(pcRows.length)}` +
    ` · product line found for ${fmt(pcRows.filter((r) => r.Product_Line).length)} of ${fmt(pcRows.length)} (G367 = PQP if Tableau has none)` +
    ` · sales org found for ${fmt(looked.filter((r) => r.Sales_Org).length)} of ${fmt(looked.filter((r) => String(r.Company_Code) === 'G367').length)} G367 invoices`);
  if (looked[0]?._lookupNotes) parts.push(`Columns used – ${looked[0]._lookupNotes}`);
} catch (e) { /* step not in this workflow */ }
if (!duplicates.length && !unreadable.length && !Object.keys(issues).length) parts.push('no data quality issues found');

return [{
  json: {
    file: FILE_NAME,
    rowsRead: raw.length,
    rowsSaved: rows.length,
    blankRows: blank,
    unreadableInvoices: unreadable,
    duplicateInvoices: duplicates,
    issues,
    message: parts.join(' · '),
  },
}];

// Build Report — incoming volume, watchlist, company code & customer split, weekly/monthly trends,
// workload heatmap and forecast. Fixed rules only: the same data and choices always give the same report.
// The email shows the report; the attached dashboard.html lets you change period / company code / customer.
const RECIPIENTS = ['']; // put your email between the quotes, e.g. ['name.surname@company.com']
const RULES = {
  spike: 1.5, // flag when a customer's invoices are 50%+ above their usual (average of previous 3 periods)
  fall: 0.5, // flag when an active customer falls 50%+ below their usual
  share: 0.2, // flag when one customer is over 20% of the period's value
  slowDays: 3, // flag when average Received → Allocated takes more than 3 days
  minInvoices: 3, // ignore customers with fewer invoices than this for spike / fall / turnaround / portal flags
};

// ---------- shared helpers (also embedded in the dashboard) ----------
function analyse(all, opts, RULES) {
  const DAY = 86400000;
  const ms = (d) => Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10));
  const iso = (t) => new Date(t).toISOString().slice(0, 10);
  const addDays = (d, n) => iso(ms(d) + n * DAY);
  const weekStart = (d) => addDays(d, -((new Date(ms(d)).getUTCDay() + 6) % 7)); // Monday
  const monthStart = (d) => d.slice(0, 8) + '01';
  const monthEnd = (d) => iso(Date.UTC(+d.slice(0, 4), +d.slice(5, 7), 0));
  const addMonths = (d, n) => iso(Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1 + n, 1));
  const num = (v) => { const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : 0; };
  const sum = (a, f) => a.reduce((s, r) => s + f(r), 0);

  const dates = all.map((r) => r.d).filter(Boolean).sort();
  if (!dates.length) return { empty: true };
  const first = dates[0];
  const latest = dates[dates.length - 1];

  // ----- period -----
  let from, to, label;
  const type = opts.type || 'Overview';
  if (type === 'Weekly') { from = weekStart(latest); to = addDays(from, 6); label = `Week of ${from}`; }
  else if (type === 'Custom period') {
    from = opts.from || first; to = opts.to || latest; label = `${from} to ${to}`;
  } else { from = monthStart(latest); to = monthEnd(latest); label = type === 'Monthly' ? from.slice(0, 7) : `${from.slice(0, 7)} (month to date)`; }
  if (to < from) [from, to] = [to, from];
  const len = Math.round((ms(to) - ms(from)) / DAY) + 1;
  const shift = (k) => type === 'Weekly' || type === 'Custom period'
    ? [addDays(from, -len * k), addDays(from, -len * (k - 1) - 1)]
    : [addMonths(from, -k), monthEnd(addMonths(from, -k))];

  const cc = String(opts.companyCode || '').trim().toUpperCase();
  const cust = String(opts.customer || '').trim().toUpperCase();
  const pcSel = String(opts.profitCentre || '').trim().toUpperCase();
  const plSel = String(opts.productLine || '').trim().toUpperCase();
  const pcKey = (r) => r.pc || 'NOT FOUND';
  const plKey = (r) => r.pl || 'NOT FOUND';
  const scoped = all.filter((r) => r.d && (!cc || r.cc === cc) && (!cust || r.c.includes(cust))
    && (!pcSel || pcKey(r) === pcSel) && (!plSel || plKey(r) === plSel));
  const inRange = (a, b) => scoped.filter((r) => r.d >= a && r.d <= b);
  const cur = inRange(from, to);
  const [pf, pt] = shift(1);
  const prev = inRange(pf, pt);
  // baseline = previous 3 periods, but only those fully covered by data (so the start of the data isn't a fake "spike")
  const base = [1, 2, 3].map((k) => shift(k)).filter(([a]) => a >= first).map(([a, b]) => inRange(a, b));

  const tat = (r) => (r.rd && r.ad ? Math.max(0, Math.round((ms(r.ad) - ms(r.rd)) / DAY)) : null);
  const avgTat = (rows) => { const t = rows.map(tat).filter((x) => x !== null); return t.length ? sum(t, (x) => x) / t.length : null; };
  const channel = (r) => (!r.p ? 'Not recorded' : r.p.includes('@') ? 'Email' : `Portal: ${r.p.split(/[,;]/)[0].trim()}`);
  const groupBy = (rows, key) => {
    const m = new Map();
    for (const r of rows) { const k = key(r); if (!k) continue; const g = m.get(k) || { key: k, n: 0, v: 0, rows: [] }; g.n++; g.v += num(r.v); g.rows.push(r); m.set(k, g); }
    return [...m.values()];
  };
  const byValue = (a, b) => b.v - a.v || String(a.key).localeCompare(String(b.key));
  const change = (now, before) => (before ? (now - before) / before : null);

  const total = { n: cur.length, v: sum(cur, (r) => num(r.v)) };
  const prevTotal = { n: prev.length, v: sum(prev, (r) => num(r.v)) };

  // ----- watchlist -----
  const firstSeen = new Map();
  for (const r of all) if (r.d && (!firstSeen.has(r.c) || r.d < firstSeen.get(r.c))) firstSeen.set(r.c, r.d);
  const watch = [];
  for (const g of groupBy(cur, (r) => r.c).sort(byValue)) {
    const usual = base.length ? sum(base, (rows) => rows.filter((r) => r.c === g.key).length) / base.length : 0;
    const reasons = [];
    if (firstSeen.get(g.key) >= from) reasons.push(['New customer', `first invoice ${firstSeen.get(g.key)}`]);
    else if (g.n >= RULES.minInvoices && usual > 0 && g.n >= usual * RULES.spike) reasons.push(['Volume spike', `${g.n} invoices vs usual ${usual.toFixed(1)}`]);
    if (total.v && g.v / total.v > RULES.share) reasons.push(['High value share', `${(100 * g.v / total.v).toFixed(1)}% of value`]);
    const t = avgTat(g.rows);
    if (g.n >= RULES.minInvoices && t !== null && t > RULES.slowDays) reasons.push(['Slow turnaround', `${t.toFixed(1)} days received → allocated`]);
    const portal = g.rows.filter((r) => channel(r).startsWith('Portal'));
    if (portal.length >= RULES.minInvoices) reasons.push(['Portal submissions', `${portal.length} via ${channel(portal[0]).slice(8)}`]);
    const missing = g.rows.filter((r) => !num(r.v)).length;
    if (missing) reasons.push(['Data issue', `${missing} without a value`]);
    if (reasons.length) watch.push({ customer: g.key, n: g.n, v: g.v, reasons });
  }
  const curCustomers = new Set(cur.map((r) => r.c));
  const usualAll = new Map();
  for (const rows of base) for (const r of rows) usualAll.set(r.c, (usualAll.get(r.c) || 0) + 1 / base.length);
  for (const [c, usual] of [...usualAll].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))) {
    const n = cur.filter((r) => r.c === c).length;
    if (usual >= RULES.minInvoices && n <= usual * RULES.fall) {
      const item = { customer: c, n, v: sum(cur.filter((r) => r.c === c), (r) => num(r.v)), reasons: [[n ? 'Sharp fall' : 'Gone quiet', `${n} invoices vs usual ${usual.toFixed(1)}`]] };
      if (curCustomers.has(c)) { const w = watch.find((x) => x.customer === c); if (w) w.reasons.push(item.reasons[0]); else watch.push(item); } else watch.push(item);
    }
  }

  // ----- trends -----
  const monthsBack = [];
  for (let k = 11; k >= 0; k--) monthsBack.push(addMonths(monthStart(to), -k));
  const monthly = monthsBack.map((m) => { const rows = scoped.filter((r) => r.d >= m && r.d <= monthEnd(m)); return { key: m.slice(0, 7), n: rows.length, v: sum(rows, (r) => num(r.v)) }; })
    .filter((m, i, a) => m.n || a.slice(0, i).some((x) => x.n));
  const weeksBack = [];
  for (let k = 7; k >= 0; k--) weeksBack.push(addDays(weekStart(to), -7 * k));
  const weekly = weeksBack.map((w) => { const rows = scoped.filter((r) => r.d >= w && r.d <= addDays(w, 6)); return { key: w, n: rows.length, v: sum(rows, (r) => num(r.v)) }; });
  const heat = monthsBack.slice(-6).map((m) => {
    const cells = Array.from({ length: 31 }, (_, i) => scoped.filter((r) => r.d.slice(0, 7) === m.slice(0, 7) && +r.d.slice(8, 10) === i + 1).length);
    return { key: m.slice(0, 7), cells };
  });
  const wd = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const last12w = scoped.filter((r) => r.d > addDays(to, -84) && r.d <= to);
  const weekday = wd.map((name, i) => ({ key: name, n: last12w.filter((r) => (new Date(ms(r.d)).getUTCDay() + 6) % 7 === i).length / 12 }));

  // ----- forecast (averages of recent complete periods; range = lowest–highest of those periods) -----
  const doneWeeks = [];
  for (let k = 8; k >= 1; k--) { const w = addDays(weekStart(latest), -7 * k); const rows = scoped.filter((r) => r.d >= w && r.d <= addDays(w, 6)); doneWeeks.push({ n: rows.length, v: sum(rows, (r) => num(r.v)) }); }
  const doneMonths = [];
  for (let k = 3; k >= 1; k--) { const m = addMonths(monthStart(latest), -k); const rows = scoped.filter((r) => r.d >= m && r.d <= monthEnd(m)); doneMonths.push({ n: rows.length, v: sum(rows, (r) => num(r.v)) }); }
  const stat = (a, f) => ({ avg: a.length ? sum(a, f) / a.length : 0, lo: a.length ? Math.min(...a.map(f)) : 0, hi: a.length ? Math.max(...a.map(f)) : 0 });
  const forecast = {
    weekN: stat(doneWeeks, (x) => x.n), weekV: stat(doneWeeks, (x) => x.v),
    monthN: stat(doneMonths, (x) => x.n), monthV: stat(doneMonths, (x) => x.v),
    nextWeeks: [1, 2, 3, 4].map((k) => addDays(weekStart(latest), 7 * k)),
    nextMonth: addMonths(monthStart(latest), 1).slice(0, 7),
  };

  // ----- splits -----
  const companies = groupBy(cur, (r) => r.cc || 'UNKNOWN').sort(byValue).map((g) => ({
    key: g.key, n: g.n, v: g.v, prevN: prev.filter((r) => (r.cc || 'UNKNOWN') === g.key).length,
    top: groupBy(g.rows, (r) => r.c).sort(byValue).slice(0, 5),
  }));
  const split = (keyOf) => groupBy(cur, keyOf).sort(byValue).map((g) => ({
    key: g.key, n: g.n, v: g.v, prevN: prev.filter((r) => keyOf(r) === g.key).length, tat: avgTat(g.rows),
    top: groupBy(g.rows, (r) => r.c).sort(byValue).slice(0, 5),
  }));
  const profitCentres = split(pcKey);
  const productLines = split(plKey);
  // ----- breakdown tree: entity → company code → sales org → (profit centre, product line) -----
  const ENTITY = { '3060': 'LA PRAIRIE (CANADA)', '3487': 'LA PRAIRIE (CANADA)', '3485': 'CHARLEROI', G367: 'CLEARWATER' };
  const LEVEL = {
    entity: { name: 'Entity', of: (r) => ENTITY[r.cc] || (r.cc ? 'OTHER' : '') },
    cc: { name: 'Company code', of: (r) => r.cc || '' },
    so: { name: 'Sales org', of: (r) => r.so || '' },
    pc: { name: 'Profit centre', of: (r) => r.pc || '' },
    pl: { name: 'Product line', of: (r) => r.pl || '' },
  };
  // values of `child` that appear under more than one value of `parent` (checked on all data, not just this period)
  const clashes = (parent, child) => {
    const m = new Map();
    for (const r of scoped) {
      const c = LEVEL[child].of(r); const pv = LEVEL[parent].of(r);
      if (!c || !pv) continue;
      if (!m.has(c)) m.set(c, new Set());
      m.get(c).add(pv);
    }
    return [...m].filter(([, set]) => set.size > 1).map(([c]) => c).sort();
  };
  // order of the two lower levels: the one with the fewest clashes; a tie keeps the expected order (first in the list)
  const ORDERS = [['pc', 'pl'], ['pl', 'pc']];
  const scored = ORDERS.map((o, i) => ({ o, i, n: clashes('cc', o[0]).length + clashes(o[0], o[1]).length }));
  const lower = scored.sort((x, y) => x.n - y.n || x.i - y.i)[0].o;
  const levels = ['entity', 'cc', 'so', ...lower];
  const structure = {
    order: levels.map((k) => LEVEL[k].name),
    // sales org only exists for G367, so the lower levels are checked against the company code
    exceptions: [['entity', 'cc'], ['cc', 'so'], ['cc', lower[0]], [lower[0], lower[1]]]
      .map(([pk, ck]) => ({ parent: LEVEL[pk].name, child: LEVEL[ck].name, values: clashes(pk, ck) }))
      .filter((e) => e.values.length),
  };
  // only overlaps at the top (e.g. one profit centre under two company codes) are data problems;
  // lower down, e.g. one product line under several profit centres, is normal and simply repeats under each parent
  structure.problems = structure.exceptions.filter((e) => ['Entity', 'Company code', 'Sales org'].includes(e.parent));
  const MAX_CHILDREN = 8;
  const buildTree = (curRows, prevRows, depth) => {
    if (depth >= levels.length || !curRows.length) return [];
    const lv = LEVEL[levels[depth]];
    // an empty value (e.g. no sales org, no profit centre for G367) skips the level instead of adding a blank row
    if (curRows.every((r) => !lv.of(r))) return buildTree(curRows, prevRows, depth + 1);
    const nodes = groupBy(curRows, (r) => lv.of(r) || '(not set)').sort(byValue).map((g) => {
      const pr = prevRows.filter((r) => (lv.of(r) || '(not set)') === g.key);
      let node = { label: g.key, level: lv.name, n: g.n, v: g.v, prevN: pr.length, tat: avgTat(g.rows), children: buildTree(g.rows, pr, depth + 1) };
      // one child with the same invoices = the same thing again: show it on the same line
      while (node.children.length === 1 && node.children[0].n === node.n) {
        const c = node.children[0];
        node = { ...node, label: `${node.label} › ${c.label}`, level: `${node.level} › ${c.level}`, children: c.children, more: c.more };
      }
      return node;
    });
    const shown = nodes.slice(0, MAX_CHILDREN);
    if (nodes.length > MAX_CHILDREN) {
      const rest = nodes.slice(MAX_CHILDREN);
      shown.push({ label: `+ ${rest.length} more`, level: lv.name, n: sum(rest, (x) => x.n), v: sum(rest, (x) => x.v), prevN: null, tat: null, children: [] });
    }
    return shown;
  };
  const tree = buildTree(cur, prev, 0);
  const mostCommon = (rows, f) => groupBy(rows, f).sort((a, b) => b.n - a.n || String(a.key).localeCompare(String(b.key)))[0]?.key || '';
  const customers = groupBy(cur, (r) => r.c).sort(byValue).slice(0, 15).map((g) => ({
    key: g.key, n: g.n, v: g.v, tat: avgTat(g.rows), prevN: prev.filter((r) => r.c === g.key).length,
    pc: mostCommon(g.rows, (r) => r.pc), pl: mostCommon(g.rows, (r) => r.pl), sap: mostCommon(g.rows, (r) => r.sap),
    trend: monthsBack.slice(-6).map((m) => scoped.filter((r) => r.c === g.key && r.d.slice(0, 7) === m.slice(0, 7)).length),
  }));
  const channels = groupBy(cur, channel).sort((a, b) => b.n - a.n);
  const managers = groupBy(cur, (r) => r.pm || 'Not recorded').sort((a, b) => b.n - a.n);
  const quality = {
    noValue: cur.filter((r) => !num(r.v)).length,
    repeated: groupBy(cur, (r) => String(r.i)).filter((g) => g.n > 1).map((g) => g.key),
    allocatedBeforeReceived: cur.filter((r) => r.rd && r.ad && r.ad < r.rd).length,
  };

  return {
    label, type, from, to, first, latest, cc, cust, pcSel, plSel, profitCentres, productLines, tree, structure, total, prevTotal, avgTat: avgTat(cur), baseN: base.length,
    nChange: change(total.n, prevTotal.n), vChange: change(total.v, prevTotal.v),
    watch, monthly, weekly, heat, weekday, forecast, companies, customers, channels, managers, quality,
  };
}

function render(a) {
  if (a.empty) return '<p>No data for this selection.</p>';
  const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const money = (n) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const int = (n) => Math.round(n).toLocaleString('en-US');
  const pct = (x) => (x === null || x === undefined ? '–' : `${x >= 0 ? '▲' : '▼'} ${Math.abs(100 * x).toFixed(1)}%`);
  const share = (p, w) => (w ? `${(100 * p / w).toFixed(1)}%` : '–');
  const C = { ink: '#111827', mute: '#6b7280', line: '#e5e7eb', head: '#1f3a5f', bar: '#2b6cb0', warn: '#b45309', bad: '#b91c1c', good: '#047857' };
  const th = (t, right) => `<th style="text-align:${right ? 'right' : 'left'};padding:6px 10px;background:${C.head};color:#fff;font-weight:600;font-size:12px">${esc(t)}</th>`;
  const td = (t, right, color) => `<td style="padding:5px 10px;border-bottom:1px solid ${C.line};font-size:12px;${right ? 'text-align:right;' : ''}${color ? `color:${color};` : ''}">${t}</td>`;
  const bar = (part, whole, color = C.bar) => `<table cellpadding="0" cellspacing="0" width="${Math.max(2, Math.round(100 * part / (whole || 1)))}%"><tr><td bgcolor="${color}" height="10" style="font-size:0;line-height:0">&nbsp;</td></tr></table>`;
  const table = (heads, rows) => `<table cellspacing="0" cellpadding="0" style="border-collapse:collapse;width:100%;max-width:860px">` +
    `<tr>${heads.map((h, i) => th(h, i > 0 && h !== '')).join('')}</tr>${rows.join('') || `<tr>${td('No data')}</tr>`}</table>`;
  const h = (t, sub) => `<h3 style="margin:26px 0 4px;color:${C.head};font-size:16px">${esc(t)}</h3>${sub ? `<div style="color:${C.mute};font-size:12px;margin-bottom:8px">${esc(sub)}</div>` : ''}`;
  const kpi = (label, value, note) => `<td style="padding:10px 16px;border:1px solid ${C.line};vertical-align:top"><div style="font-size:11px;color:${C.mute}">${esc(label)}</div>` +
    `<div style="font-size:20px;font-weight:700;color:${C.ink}">${esc(value)}</div><div style="font-size:11px;color:${C.mute}">${esc(note || '')}</div></td>`;
  const changeColor = (x) => (x === null ? C.mute : x >= 0 ? C.good : C.bad);
  const flagColor = { 'Volume spike': C.warn, 'Sharp fall': C.bad, 'Gone quiet': C.bad, 'New customer': C.bar, 'High value share': C.warn, 'Slow turnaround': C.bad, 'Portal submissions': C.head, 'Data issue': C.bad };

  const maxM = Math.max(1, ...a.monthly.map((m) => m.n));
  const maxW = Math.max(1, ...a.weekly.map((w) => w.n));
  const maxH = Math.max(1, ...a.heat.flatMap((r) => r.cells));
  const hex2 = (x) => Math.round(x).toString(16).padStart(2, '0');
  const shade = (n) => { if (!n) return '#f9fafb'; const t = n / maxH; const mix = (x, y) => x + (y - x) * t; return `#${hex2(mix(219, 30))}${hex2(mix(234, 64))}${hex2(mix(254, 175))}`; };
  const maxWd = Math.max(1, ...a.weekday.map((w) => w.n));
  const f = a.forecast;
  const scope = [a.cc && `company code ${a.cc}`, a.pcSel && `profit centre ${a.pcSel}`, a.plSel && `product line ${a.plSel}`,
    a.cust && `customer contains "${a.cust}"`].filter(Boolean).join(', ') || 'all company codes, profit centres, product lines and customers';
  const treeRows = (nodes, depth) => nodes.flatMap((nd) => {
    const ch = nd.prevN ? (nd.n - nd.prevN) / nd.prevN : null;
    const name = depth === 0 ? `<b>${esc(nd.label)}</b>` : `<span style="color:${depth > 1 ? C.mute : C.ink}">${'&nbsp;'.repeat(depth * 4)}↳ ${esc(nd.label)}</span>`;
    const row = `<tr>${td(name)}${td(`<span style="color:${C.mute};font-size:11px">${esc(nd.level)}</span>`)}${td(int(nd.n), 1)}${td(money(nd.v), 1)}${td(share(nd.v, a.total.v), 1)}` +
      `${td(nd.prevN === null ? '' : pct(ch), 1, changeColor(ch))}${td(nd.tat === null ? '–' : nd.tat.toFixed(1), 1)}</tr>`;
    return [row, ...treeRows(nd.children, depth + 1)];
  });

  return `<div style="font-family:Segoe UI,Arial,sans-serif;color:${C.ink};max-width:900px">
<h2 style="margin:0;color:${C.head}">Production Tracker – ${esc(a.type)} report</h2>
<div style="color:${C.mute};font-size:12px">${esc(a.label)} · ${esc(a.from)} to ${esc(a.to)} · ${esc(scope)} · data from ${esc(a.first)} to ${esc(a.latest)}</div>
<table cellspacing="0" style="border-collapse:collapse;margin:14px 0"><tr>
${kpi('Incoming invoices', int(a.total.n), `${pct(a.nChange)} vs previous period`)}${kpi('Value', money(a.total.v), `${pct(a.vChange)} vs previous period`)}
${kpi('Avg received → allocated', a.avgTat === null ? '–' : `${a.avgTat.toFixed(1)} days`, '')}${kpi('Next week (forecast)', int(f.weekN.avg), `range ${int(f.weekN.lo)}–${int(f.weekN.hi)}`)}
</tr></table>
${h(`Customers to look out for (${a.watch.length})`, `Fixed rules: spike / fall vs the previous ${a.baseN} period(s) with full data, value share, turnaround, portal use, data issues`)}
${table(['Customer', 'Invoices', 'Value', 'Why'], a.watch.slice(0, 20).map((w) => `<tr>${td(esc(w.customer))}${td(int(w.n), 1)}${td(money(w.v), 1)}${td(w.reasons.map(([k, d]) => `<b style="color:${flagColor[k] || C.ink}">${esc(k)}</b> – ${esc(d)}`).join('<br>'))}</tr>`))}
${h('Incoming volume by month', 'Invoices received per month, with change from the month before')}
${table(['Month', 'Invoices', 'Value', 'Change', ''], a.monthly.map((m, i) => { const c = i ? (a.monthly[i - 1].n ? (m.n - a.monthly[i - 1].n) / a.monthly[i - 1].n : null) : null; return `<tr>${td(m.key)}${td(int(m.n), 1)}${td(money(m.v), 1)}${td(pct(c), 1, changeColor(c))}<td style="padding:5px 10px;border-bottom:1px solid ${C.line};width:35%">${bar(m.n, maxM)}</td></tr>`; }))}
${h('Weekly details (last 8 weeks)', 'Weeks start on Monday')}
${table(['Week starting', 'Invoices', 'Value', ''], a.weekly.map((w) => `<tr>${td(w.key)}${td(int(w.n), 1)}${td(money(w.v), 1)}<td style="padding:5px 10px;border-bottom:1px solid ${C.line};width:40%">${bar(w.n, maxW)}</td></tr>`))}
${h('Workload heatmap – day of month', 'Darker = more invoices received that day (last 6 months)')}
<table cellspacing="1" cellpadding="0" style="font-size:10px"><tr><td style="padding:2px 6px"></td>${Array.from({ length: 31 }, (_, i) => `<td style="text-align:center;color:${C.mute};width:20px">${i + 1}</td>`).join('')}</tr>
${a.heat.map((r) => `<tr><td style="padding:2px 6px;color:${C.mute};white-space:nowrap">${r.key}</td>${r.cells.map((n) => `<td bgcolor="${shade(n)}" style="text-align:center;height:20px;color:${n / maxH > 0.55 ? '#fff' : C.ink}">${n || ''}</td>`).join('')}</tr>`).join('')}</table>
${h('Busiest weekdays', 'Average invoices received per weekday (last 12 weeks)')}
${table(['Weekday', 'Avg invoices', ''], a.weekday.map((w) => `<tr>${td(w.key)}${td(w.n.toFixed(1), 1)}<td style="padding:5px 10px;border-bottom:1px solid ${C.line};width:50%">${bar(w.n, maxWd)}</td></tr>`))}
${h('Forecast', 'Average of recent complete periods; range = lowest–highest of those periods')}
${table(['Period', 'Expected invoices', 'Range', 'Expected value'], [
    ...f.nextWeeks.map((w) => `<tr>${td(`Week of ${w}`)}${td(int(f.weekN.avg), 1)}${td(`${int(f.weekN.lo)}–${int(f.weekN.hi)}`, 1)}${td(money(f.weekV.avg), 1)}</tr>`),
    `<tr>${td(`<b>${f.nextMonth}</b>`)}${td(`<b>${int(f.monthN.avg)}</b>`, 1)}${td(`${int(f.monthN.lo)}–${int(f.monthN.hi)}`, 1)}${td(`<b>${money(f.monthV.avg)}</b>`, 1)}</tr>`])}
${h('Breakdown: ' + a.structure.order.join(' → '), 'One line per group; a level is skipped where it does not apply (e.g. sales org outside G367), and repeated single groups are shown on one line')}
${table(['Group', 'Level', 'Invoices', 'Value', 'Share', 'vs previous', 'Avg days'], treeRows(a.tree, 0))}
${a.structure.problems.length ? `<div style="font-size:11px;color:${C.warn};margin-top:4px">Check the data: ${a.structure.problems.map((e) =>
    `${e.values.length} ${esc(e.child.toLowerCase())}(s) appear under more than one ${esc(e.parent.toLowerCase())} (${esc(e.values.slice(0, 5).join(', '))}${e.values.length > 5 ? ' …' : ''})`).join('; ')}</div>` : ''}
${h('Customer details (top 15 by value)', 'Trend = invoices per month, last 6 months')}
${table(['Customer', 'SAP code', 'Profit centre', 'Product line', 'Invoices', 'Value', 'Share', 'Avg days', 'Trend'], a.customers.map((c) => `<tr>${td(esc(c.key))}${td(esc(c.sap || '–'))}${td(esc(c.pc || '–'))}${td(esc(c.pl || '–'))}${td(int(c.n), 1)}${td(money(c.v), 1)}${td(share(c.v, a.total.v), 1)}${td(c.tat === null ? '–' : c.tat.toFixed(1), 1)}${td(c.trend.join(' · '), 1)}</tr>`))}
${h('Channels & project managers')}
${table(['Channel', 'Invoices', 'Share'], a.channels.map((c) => `<tr>${td(esc(c.key))}${td(int(c.n), 1)}${td(share(c.n, a.total.n), 1)}</tr>`))}
<div style="height:10px"></div>
${table(['Project manager', 'Invoices', 'Value'], a.managers.map((m) => `<tr>${td(esc(m.key))}${td(int(m.n), 1)}${td(money(m.v), 1)}</tr>`))}
${h('Data quality')}
<ul style="font-size:12px;margin:0;padding-left:18px">
<li>${int(a.quality.noValue)} invoices without a value</li>
<li>${int(a.quality.allocatedBeforeReceived)} allocated before received</li>
<li>${a.quality.repeated.length ? `${a.quality.repeated.length} invoice numbers appear more than once: ${esc(a.quality.repeated.slice(0, 10).join(', '))}${a.quality.repeated.length > 10 ? ' …' : ''}` : 'No repeated invoice numbers'}</li></ul>
<p style="color:#9ca3af;font-size:11px;margin-top:22px">Generated by n8n from the Production Tracker data table. Workload date = Received_Date (falls back to Allocated, then Invoice date).</p>
</div>`;
}

// ---------- main ----------
const settings = { type: 'Overview', source: 'form' };
const seen = new Map(); // one row per invoice (last row wins)
for (const { json: r } of $('Add Lookups').all()) {
  const d = r.Received_Date || r.Allocated_Date || r.Invoice_Date || '';
  seen.set(String(r.Invoice ?? r.id), {
    i: r.Invoice, d: String(d).slice(0, 10), rd: String(r.Received_Date || '').slice(0, 10), ad: String(r.Allocated_Date || '').slice(0, 10),
    c: String(r.Customer || 'UNKNOWN CUSTOMER').trim().toUpperCase(), cc: String(r.Company_Code || '').trim().toUpperCase(),
    pm: String(r.Project_Manager || '').trim(), p: String(r.Name_the_PortalEmail_ID || '').trim(), v: r.Value,
    sap: String(r.SAP_Customer_Code || '').trim(), pc: String(r.Profit_Center || '').trim().toUpperCase(),
    so: String(r.Sales_Org || '').trim().toUpperCase(),
    pl: String(r.Product_Line || '').trim().toUpperCase(),
  });
}
const rows = [...seen.values()];
const a = analyse(rows, settings, RULES);
const html = render(a);

const recipients = String(settings.sendTo || '').trim() || RECIPIENTS.filter((x) => String(x).trim()).join(', ');
if (!recipients) throw new Error('Add at least one email address to RECIPIENTS at the top of "Build Report".');

const safeJson = (x) => JSON.stringify(x).replace(/</g, '\\u003c');
const companyCodes = [...new Set(rows.map((r) => r.cc).filter(Boolean))].sort();
const listOf = (f) => [...new Set(rows.map(f))].sort();
const options = (list) => list.map((c) => `<option>${String(c).replace(/[&<>"]/g, '')}</option>`).join('');
const profitCentreList = listOf((r) => r.pc || 'NOT FOUND');
const productLineList = listOf((r) => r.pl || 'NOT FOUND');
const dashboard = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Production Tracker Dashboard</title></head><body style="margin:0;padding:18px;background:#fff">
<!--charts-->
<div style="font-family:Segoe UI,Arial,sans-serif;font-size:13px;background:#f3f4f6;padding:12px;border-radius:6px;margin-bottom:12px;max-width:900px">
<b>Choose:</b> Report <select id="t"><option>Overview</option><option>Weekly</option><option>Monthly</option><option>Custom period</option></select>
From <input id="f" type="date"> To <input id="o" type="date">
Company code <select id="cc"><option value="">All</option>${companyCodes.map((c) => `<option>${c}</option>`).join('')}</select>
Profit centre <select id="pc"><option value="">All</option>${options(profitCentreList)}</select>
Product line <select id="pl"><option value="">All</option>${options(productLineList)}</select>
Customer contains <input id="cu" size="18"> <button id="go">Show</button></div>
<div id="out"></div>
<script>
const ROWS = ${safeJson(rows)};
const RULES = ${safeJson(RULES)};
${analyse.toString()}
${render.toString()}
const $id = (x) => document.getElementById(x);
function show() {
  const opts = { type: $id('t').value, from: $id('f').value, to: $id('o').value, companyCode: $id('cc').value, customer: $id('cu').value, profitCentre: $id('pc').value, productLine: $id('pl').value };
  if ((opts.from || opts.to) && opts.type !== 'Custom period') { opts.type = 'Custom period'; $id('t').value = opts.type; }
  $id('out').innerHTML = render(analyse(ROWS, opts, RULES));
}
const start = ${safeJson({ type: settings.type || 'Overview', from: settings.from || '', to: settings.to || '', companyCode: settings.companyCode || '', customer: settings.customer || '' })};
$id('t').value = start.type; $id('f').value = start.from; $id('o').value = start.to; $id('cc').value = start.companyCode.toUpperCase(); $id('cu').value = start.customer;
$id('go').onclick = show; show();
</script></body></html>`;

const quality = (() => { try { return $('Summarise Upload').first().json.message; } catch (e) { return ''; } })();

// Compact facts for the AI commentary step (the AI may only use these figures)
const r2 = (x) => Math.round(x * 100) / 100;
const p1 = (x) => (x === null || x === undefined ? null : Math.round(x * 1000) / 10);
const facts = a.empty ? { empty: true } : {
  report: a.type, period: `${a.from} to ${a.to}`, scope: { companyCode: a.cc || 'all', profitCentre: a.pcSel || 'all', productLine: a.plSel || 'all', customer: a.cust || 'all' },
  invoices: a.total.n, value: r2(a.total.v),
  previousPeriod: { invoices: a.prevTotal.n, value: r2(a.prevTotal.v) },
  changePercent: { invoices: p1(a.nChange), value: p1(a.vChange) },
  avgDaysReceivedToAllocated: a.avgTat === null ? null : r2(a.avgTat),
  watchlist: a.watch.slice(0, 10).map((w) => ({ customer: w.customer, invoices: w.n, value: r2(w.v), flags: w.reasons.map(([k, d]) => `${k}: ${d}`) })),
  monthly: a.monthly.slice(-6).map((m) => ({ month: m.key, invoices: m.n, value: r2(m.v),
    ...(m.key === a.latest.slice(0, 7) && a.latest.slice(8, 10) !== String(new Date(Date.UTC(+m.key.slice(0, 4), +m.key.slice(5, 7), 0)).getUTCDate())
      ? { monthToDate: true } : {}) })),
  weekly: a.weekly.map((w) => ({ weekStarting: w.key, invoices: w.n, value: r2(w.v) })),
  busiestDaysOfMonth: Array.from({ length: 31 }, (_, d) => ({ day: d + 1, avgInvoices: r2(a.heat.reduce((s, m) => s + m.cells[d], 0) / Math.max(1, a.heat.length)) }))
    .sort((x, y) => y.avgInvoices - x.avgInvoices || x.day - y.day).slice(0, 5),
  busiestWeekdays: [...a.weekday].sort((x, y) => y.n - x.n).slice(0, 3).map((w) => ({ weekday: w.key, avgInvoices: r2(w.n) })),
  forecast: {
    nextWeekInvoices: { expected: Math.round(a.forecast.weekN.avg), low: a.forecast.weekN.lo, high: a.forecast.weekN.hi },
    nextMonth: { month: a.forecast.nextMonth, expectedInvoices: Math.round(a.forecast.monthN.avg), low: a.forecast.monthN.lo, high: a.forecast.monthN.hi, expectedValue: r2(a.forecast.monthV.avg) },
  },
  companyCodes: a.companies.map((c) => ({ code: c.key, invoices: c.n, value: r2(c.v), valueSharePercent: a.total.v ? p1(c.v / a.total.v) : null, previousPeriodInvoices: c.prevN, topCustomers: c.top.slice(0, 3).map((t) => t.key) })),
  structure: { order: a.structure.order, exceptions: a.structure.exceptions.map((e) => `${e.values.length} ${e.child} values under more than one ${e.parent}`) },
  breakdown: (function flat(nodes, depth, path) { return nodes.flatMap((nd) => [{ group: [...path, nd.label].join(' / '), level: nd.level, invoices: nd.n, value: r2(nd.v), previousPeriodInvoices: nd.prevN },
    ...(depth < 2 ? flat(nd.children, depth + 1, [...path, nd.label]) : [])]); })(a.tree, 0, []).slice(0, 40),
  profitCentres: a.profitCentres.slice(0, 12).map((c) => ({ profitCentre: c.key, invoices: c.n, value: r2(c.v), valueSharePercent: a.total.v ? p1(c.v / a.total.v) : null, previousPeriodInvoices: c.prevN, avgDays: c.tat === null ? null : r2(c.tat), topCustomers: c.top.slice(0, 3).map((t) => t.key) })),
  productLines: a.productLines.map((c) => ({ productLine: c.key, invoices: c.n, value: r2(c.v), previousPeriodInvoices: c.prevN })),
  topCustomers: a.customers.slice(0, 8).map((c) => ({ customer: c.key, sapCode: c.sap || null, profitCentre: c.pc || null, invoices: c.n, value: r2(c.v), avgDays: c.tat === null ? null : r2(c.tat), invoicesLast6Months: c.trend })),
  channels: a.channels.map((c) => ({ channel: c.key, invoices: c.n })),
  dataQuality: { withoutValue: a.quality.noValue, allocatedBeforeReceived: a.quality.allocatedBeforeReceived, repeatedInvoiceNumbers: a.quality.repeated.length },
};
const uploadNote = quality
  ? `<p style="font-family:Segoe UI,Arial,sans-serif;font-size:12px;color:#374151;background:#f3f4f6;padding:8px 12px;max-width:860px"><b>Upload result:</b> ${quality.replace(/[&<>]/g, '')}</p>`
  : '';
const subject = `Production Tracker ${a.type || ''} report – ${a.label || ''} – ${Math.round(a.total?.n ?? 0)} invoices, ${a.watch?.length ?? 0} customers to watch`;
return [{
  json: {
    to: recipients,
    subject,
    facts: JSON.stringify(facts),
    html: '<!--charts-->' + uploadNote + html + '<p style="font-family:Segoe UI,Arial,sans-serif;font-size:12px;color:#6b7280">The attached dashboard.html lets you change the period, company code, profit centre, product line and customer. Open it in your browser.</p>',
    doneMessage: (quality ? quality + '. ' : '') + `Report "${a.label || ''}" sent to ${recipients}.`,
  },
  binary: {
    dashboard: { data: Buffer.from(dashboard, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'dashboard.html', fileExtension: 'html' },
  },
}];

parameters.text:
=Report: {{ $json.subject }}

FACTS (JSON – the only source you may use):
{{ $json.facts }}

Write the commentary now, following the output format exactly.

parameters.jsCode:
// Add AI Commentary — put the AI's commentary above the fixed report. The figures in the report itself never come
// from the AI. If the AI step failed or returned nothing usable, the report is sent without commentary.
const base = $('Build Report').first();
const raw = String($input.first().json.text ?? $input.first().json.output ?? '');
const ALLOWED = ['h3', 'h4', 'p', 'ul', 'ol', 'li', 'b', 'strong', 'i', 'em', 'br'];

let ai = raw.replace(/```[a-z]*\n?/gi, '').replace(/<(script|style)[\s\S]*?<\/\1>/gi, '');
ai = ai.replace(/<\/?([a-z0-9]+)\b[^>]*>/gi, (tag, name) =>
  ALLOWED.includes(name.toLowerCase()) ? tag.replace(/\s[^>]*?(\/?)>$/, '$1>') : '');
if (!/<(p|li|h3)>/i.test(ai)) {
  ai = ai.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean).map((p) => `<p>${p.replace(/[&<>]/g, '')}</p>`).join('');
}

if (ai.replace(/<[^>]+>/g, '').trim().length < 40) {
  return [{ json: { ...base.json, aiUsed: false }, binary: base.binary }];
}
const box = '<div style="border-left:4px solid #2b6cb0;background:#f0f6ff;padding:10px 16px;margin:0 0 18px;' +
  'font-family:Segoe UI,Arial,sans-serif;font-size:13px;color:#111827;max-width:860px">' +
  '<div style="font-size:11px;color:#6b7280;margin-bottom:4px">AI commentary – written from the figures in this ' +
  'report. Check before acting.</div>' + ai + '</div>';
return [{ json: { ...base.json, html: box + base.json.html, aiUsed: true }, binary: base.binary }];

parameters.text:
=Report: {{ $json.subject }}

FACTS (JSON):
{{ $json.facts }}

Choose the charts now. Return only the JSON array.

parameters.jsCode:
// Add AI Charts — the "AI Chart Designer" only CHOOSES which charts to show and why.
// Every figure is taken from the facts built by "Build Report"; numbers written by the AI are never shown.
// If the AI step failed or its answer is not usable, a standard set of charts is drawn instead.
const MAX_CHARTS = 4;
const DEFAULT_CHARTS = [
  { title: 'Incoming invoices by month', dataset: 'monthly', metric: 'invoices', chart: 'column' },
  { title: 'Value by profit centre', dataset: 'profitCentres', metric: 'value', chart: 'bar' },
  { title: 'Invoices by product line', dataset: 'productLines', metric: 'invoices', chart: 'bar' },
  { title: 'Busiest weekdays', dataset: 'busiestWeekdays', metric: 'invoices', chart: 'column' },
];
// dataset → which fact field is the label and which fields hold each metric
const DATASETS = {
  monthly: { label: 'month', invoices: 'invoices', value: 'value' },
  weekly: { label: 'weekStarting', invoices: 'invoices', value: 'value' },
  busiestDaysOfMonth: { label: 'day', invoices: 'avgInvoices' },
  busiestWeekdays: { label: 'weekday', invoices: 'avgInvoices' },
  companyCodes: { label: 'code', invoices: 'invoices', value: 'value' },
  profitCentres: { label: 'profitCentre', invoices: 'invoices', value: 'value' },
  productLines: { label: 'productLine', invoices: 'invoices', value: 'value' },
  topCustomers: { label: 'customer', invoices: 'invoices', value: 'value' },
  channels: { label: 'channel', invoices: 'invoices' },
  watchlist: { label: 'customer', invoices: 'invoices', value: 'value' },
};
const TIME_SERIES = ['monthly', 'weekly'];
const COLORS = { bar: '#2b6cb0', part: '#9dbbe0', line: '#1f3a5f', grid: '#e5e7eb', ink: '#111827', mute: '#6b7280' };

const base = $('Add AI Commentary').first();
const facts = JSON.parse($('Build Report').first().json.facts || '{}');
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const fmt = (n, metric) => (metric === 'value'
  ? n.toLocaleString('en-US', { maximumFractionDigits: 0 })
  : n.toLocaleString('en-US', { maximumFractionDigits: 1 }));

// ---------- read the AI's choice (JSON list), keep only valid entries ----------
const raw = String($input.first().json.text ?? $input.first().json.output ?? '');
let picked = [];
try {
  const m = raw.replace(/```[a-z]*\n?/gi, '').match(/\[[\s\S]*\]/);
  picked = m ? JSON.parse(m[0]) : [];
} catch (e) { picked = []; }
const valid = (c) => c && DATASETS[c.dataset] && DATASETS[c.dataset][c.metric] && ['bar', 'column', 'line'].includes(c.chart)
  && Array.isArray(facts[c.dataset]) && facts[c.dataset].length >= 2;
let charts = (Array.isArray(picked) ? picked : []).filter(valid).slice(0, MAX_CHARTS).map((c) => ({
  title: String(c.title || '').replace(/[<>]/g, '').slice(0, 80) || `${c.metric} by ${c.dataset}`,
  dataset: c.dataset, metric: c.metric, chart: c.chart === 'line' && !TIME_SERIES.includes(c.dataset) ? 'bar' : c.chart,
  // a short "why", only kept if it contains no numbers (figures must come from the data, not the AI)
  why: /\d/.test(String(c.why || '')) ? '' : String(c.why || '').replace(/[<>]/g, '').slice(0, 160),
}));
const aiUsed = charts.length > 0;
if (!aiUsed) charts = DEFAULT_CHARTS.filter(valid).map((c) => ({ ...c, why: '' }));

const points = (c) => {
  const d = DATASETS[c.dataset];
  // a month that is not finished yet is marked with * and drawn lighter, so it is not read as a fall in volume
  let list = facts[c.dataset].map((x) => ({ label: String(x[d.label]) + (x.monthToDate ? '*' : ''), y: Number(x[d[c.metric]]) || 0, part: !!x.monthToDate }));
  if (!TIME_SERIES.includes(c.dataset) && c.dataset !== 'busiestWeekdays' && c.dataset !== 'busiestDaysOfMonth') {
    list = list.sort((a, b) => b.y - a.y).slice(0, 10); // biggest first, top 10
  }
  return list;
};

// ---------- email version: plain tables, works in Outlook ----------
const partNote = (pts) => (pts.some((p) => p.part)
  ? `<div style="color:${COLORS.mute};font-size:11px;margin-top:2px">* month to date – not a full month yet</div>` : '');
const emailChart = (c) => {
  const pts = points(c);
  const max = Math.max(1, ...pts.map((p) => p.y));
  const head = `<div style="font-weight:600;color:${COLORS.line};font-size:14px;margin:14px 0 2px">${esc(c.title)}</div>` +
    (c.why ? `<div style="color:${COLORS.mute};font-size:12px;margin-bottom:6px">${esc(c.why)}</div>` : '');
  if (c.chart === 'bar') {
    return head + '<table cellspacing="0" cellpadding="0" style="border-collapse:collapse;width:100%;max-width:860px;font-size:12px">' +
      pts.map((p) => `<tr><td style="padding:3px 8px 3px 0;white-space:nowrap;width:28%">${esc(p.label)}</td>` +
        `<td style="padding:3px 0;width:57%"><table cellspacing="0" cellpadding="0" width="${Math.max(2, Math.round((100 * p.y) / max))}%"><tr>` +
        `<td bgcolor="${COLORS.bar}" height="12" style="font-size:0;line-height:0">&nbsp;</td></tr></table></td>` +
        `<td style="padding:3px 0 3px 8px;text-align:right;white-space:nowrap">${fmt(p.y, c.metric)}</td></tr>`).join('') + '</table>';
  }
  const H = 110; // column (and line, drawn as columns in email)
  return head + '<table cellspacing="2" cellpadding="0" style="font-size:10px;max-width:860px"><tr>' +
    pts.map((p) => { const h = Math.max(2, Math.round((H * p.y) / max)); return `<td valign="bottom" align="center" style="padding:0 2px">` +
      `<div style="color:${COLORS.mute};font-size:10px">${fmt(p.y, c.metric)}</div>` +
      `<table cellspacing="0" cellpadding="0" width="26"><tr><td bgcolor="${p.part ? COLORS.part : COLORS.bar}" height="${h}" style="font-size:0;line-height:0">&nbsp;</td></tr></table></td>`; }).join('') +
    '</tr><tr>' + pts.map((p) => `<td align="center" style="color:${COLORS.mute};padding-top:2px;white-space:nowrap">${esc(p.label)}</td>`).join('') +
    '</tr></table>' + partNote(pts);
};

// ---------- dashboard version: real SVG charts ----------
const svgChart = (c) => {
  const pts = points(c);
  const max = Math.max(1, ...pts.map((p) => p.y));
  const W = 840; const head = `<h3 style="margin:22px 0 2px;color:${COLORS.line};font-size:15px">${esc(c.title)}</h3>` +
    (c.why ? `<div style="color:${COLORS.mute};font-size:12px;margin-bottom:6px">${esc(c.why)}</div>` : '');
  if (c.chart === 'bar') {
    const rowH = 24; const left = 200; const H = pts.length * rowH + 10;
    return head + `<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" style="font-family:Segoe UI,Arial,sans-serif;font-size:12px">` +
      pts.map((p, i) => { const w = Math.max(2, ((W - left - 90) * p.y) / max); const y = i * rowH + 4;
        return `<text x="${left - 8}" y="${y + 14}" text-anchor="end" fill="${COLORS.ink}">${esc(p.label.slice(0, 28))}</text>` +
          `<rect x="${left}" y="${y + 2}" width="${w}" height="16" rx="2" fill="${COLORS.bar}"><title>${esc(p.label)}: ${fmt(p.y, c.metric)}</title></rect>` +
          `<text x="${left + w + 6}" y="${y + 14}" fill="${COLORS.mute}">${fmt(p.y, c.metric)}</text>`; }).join('') + '</svg>';
  }
  const H = 220; const top = 16; const bottom = 34; const plotH = H - top - bottom; const step = (W - 40) / pts.length;
  const x = (i) => 30 + step * i + step / 2; const y = (v) => top + plotH - (plotH * v) / max;
  const labels = pts.map((p, i) => `<text x="${x(i)}" y="${H - 14}" text-anchor="middle" fill="${COLORS.mute}" font-size="11">${esc(p.label.slice(0, 10))}</text>`).join('');
  const grid = `<line x1="20" y1="${top + plotH}" x2="${W - 10}" y2="${top + plotH}" stroke="${COLORS.grid}"/>`;
  const marks = c.chart === 'line'
    ? `<polyline fill="none" stroke="${COLORS.line}" stroke-width="2" points="${pts.map((p, i) => (p.part ? '' : `${x(i)},${y(p.y)}`)).join(' ')}"/>` +
      // the unfinished month is joined with a dashed, lighter line
      pts.map((p, i) => (p.part && i > 0 ? `<line x1="${x(i - 1)}" y1="${y(pts[i - 1].y)}" x2="${x(i)}" y2="${y(p.y)}" stroke="${COLORS.part}" stroke-width="2" stroke-dasharray="5 4"/>` : '')).join('') +
      pts.map((p, i) => `<circle cx="${x(i)}" cy="${y(p.y)}" r="3.5" fill="${p.part ? COLORS.part : COLORS.line}"><title>${esc(p.label)}: ${fmt(p.y, c.metric)}</title></circle>` +
        `<text x="${x(i)}" y="${y(p.y) - 7}" text-anchor="middle" fill="${COLORS.mute}" font-size="10">${fmt(p.y, c.metric)}</text>`).join('')
    : pts.map((p, i) => { const bw = Math.min(46, step * 0.7); const h = Math.max(1, top + plotH - y(p.y));
      return `<rect x="${x(i) - bw / 2}" y="${top + plotH - h}" width="${bw}" height="${h}" rx="2" fill="${p.part ? COLORS.part : COLORS.bar}"><title>${esc(p.label)}: ${fmt(p.y, c.metric)}</title></rect>` +
        `<text x="${x(i)}" y="${top + plotH - h - 4}" text-anchor="middle" fill="${COLORS.mute}" font-size="10">${fmt(p.y, c.metric)}</text>`; }).join('');
  return head + `<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" style="font-family:Segoe UI,Arial,sans-serif">${grid}${marks}${labels}</svg>` + partNote(pts);
};

const note = aiUsed ? 'Charts chosen by the AI chart designer; all figures come from the report data.' : 'Standard charts.';
const emailBlock = charts.length
  ? `<div style="font-family:Segoe UI,Arial,sans-serif;max-width:860px;margin:0 0 18px;padding:6px 16px 12px;border:1px solid ${COLORS.grid}">` +
    `<div style="font-size:11px;color:${COLORS.mute};margin-top:6px">${note}</div>${charts.map(emailChart).join('')}</div>`
  : '';
const svgBlock = charts.length
  ? `<div style="font-family:Segoe UI,Arial,sans-serif;max-width:900px;margin-bottom:12px"><div style="font-size:11px;color:${COLORS.mute}">${note} These charts show the report period; use the filters below for the detailed sections.</div>${charts.map(svgChart).join('')}</div>`
  : '';

const html = String(base.json.html).replace('<!--charts-->', emailBlock);
const binary = { ...base.binary };
if (binary.dashboard?.data) {
  const page = Buffer.from(binary.dashboard.data, 'base64').toString('utf8').replace('<!--charts-->', svgBlock);
  binary.dashboard = { ...binary.dashboard, data: Buffer.from(page, 'utf8').toString('base64') };
}
return [{ json: { ...base.json, html, chartsUsed: charts.map((c) => `${c.dataset}/${c.metric}/${c.chart}`), aiCharts: aiUsed }, binary }];
